func resolveFloor(instructions string) (int, int) {
	const up = "("
	const down = ")"
	const basement = -1

	floor := 0
	var firstTimeAtBasementIndex int
	wentToBasement := false

	for index := range len(instructions) {
		switch instructions[index : index+1] {
		case up:
			floor += 1
		case down:
			floor -= 1
		default:
			fmt.Println("Unrecognized character!")
		}

		if floor == basement && wentToBasement == false {
			firstTimeAtBasementIndex = index + 1
			wentToBasement = true
		}
	}

	return floor, firstTimeAtBasementIndex
}
